import { createRequestHandler, RouterContextProvider } from "react-router";
// Generated by the dedicated build script; it is intentionally absent from source control.
// @ts-expect-error generated server bundle has no source declaration
import * as build from "./.build/server/index.js";
import { isApiOwned, resolveRedirect } from "@aihot/contracts/http-policy";
import { normalizePageRequest, pageResponse } from "./page-policy.ts";
import { SITE } from "@aihot/site";

type ServiceBinding = { fetch(request: Request, env?: unknown, ctx?: unknown): Promise<Response> };
type WorkerExecutionContext = { waitUntil(promise: Promise<unknown>): void; passThroughOnException(): void };

const routes = Object.fromEntries(Object.entries(build.routes).map(([id, route]: [string, any]) => [id,
  route?.module.default && !route.module.loader ? { ...route, module: { ...route.module, loader: () => null } } : route,
]));
const requestHandler = createRequestHandler(() => Promise.resolve({ ...build, routes }), "production");
const { runWithCloudflareRuntime } = build.entry.module;
export default {
  async fetch(request: Request, env: { API?: ServiceBinding }, ctx: WorkerExecutionContext) {
    const url = new URL(request.url);
    if (url.pathname === "/feedback") return Response.redirect(`${SITE.github}/issues`, 302);
    const redirect = resolveRedirect(url.pathname, url.search);
    if (redirect) {
      const headers = new Headers(redirect.headers);
      if (redirect.location) headers.set("Location", redirect.location);
      return new Response(redirect.location ? null : redirect.status === 410 ? "Gone" : "Not found", { status: redirect.status, headers });
    }
    if (!env.API) return new Response(JSON.stringify({ code: "api_unbound", message: "API service binding is required" }), { status: 503, headers: { "content-type": "application/json" } });
    if (isApiOwned(url.pathname)) return env.API.fetch(request);
    const context = new RouterContextProvider();
    try { request = normalizePageRequest(request); }
    catch (error) {
      if (!(error instanceof URIError)) throw error;
      return new Response("Bad request", { status: 400, headers: { "Cache-Control": "private, no-store" } });
    }
    const response = await runWithCloudflareRuntime({
      apiOrigin: "https://api.internal",
      apiFetch: (req: Request) => env.API!.fetch(req),
    }, () => requestHandler(request, context));
    return pageResponse(request, response);
  },
};
